$user_id=(int)$_SESSION['user_id'];
if(isset($_GET['ajax_action'])&&$_GET['ajax_action']==='get_details'){header('Content-Type: application/json; charset=utf-8');$order_id=(int)($_GET['id']??0);$stmt=$conn->prepare('SELECT o.*,u.fullname,u.phone,u.email FROM orders o JOIN users u ON o.user_id=u.id WHERE o.id=? AND o.user_id=?');$stmt->bind_param('ii',$order_id,$user_id);$stmt->execute();$order=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$order){echo json_encode(['status'=>'error'],JSON_UNESCAPED_UNICODE);exit;}$items=[];$stmt=$conn->prepare('SELECT oi.*,p.name,p.image FROM order_items oi JOIN products p ON oi.product_id=p.id WHERE oi.order_id=?');$stmt->bind_param('i',$order_id);$stmt->execute();$resultItems=$stmt->get_result();while($item=$resultItems->fetch_assoc()){$item['image_url']=media_url($item['image']??'',$base_url);$items[]=$item;}$stmt->close();$history=get_order_status_history($conn,$order_id);echo json_encode(['status'=>'success','order'=>$order,'items'=>$items,'history'=>$history],JSON_UNESCAPED_UNICODE);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='cancel_order'){csrf_guard();$order_id=(int)($_POST['order_id']??0);$check=$conn->prepare("SELECT id FROM orders WHERE id=? AND user_id=? AND status='pending' AND payment_status<>'paid'");$check->bind_param('ii',$order_id,$user_id);$check->execute();$res=$check->get_result();if($res->num_rows>0){$itemsStmt=$conn->prepare('SELECT product_id,variant_id,quantity FROM order_items WHERE order_id=?');$itemsStmt->bind_param('i',$order_id);$itemsStmt->execute();$itemsRes=$itemsStmt->get_result();while($item=$itemsRes->fetch_assoc()){$productId=(int)$item['product_id'];$variantId=(int)($item['variant_id']??0);$quantity=(int)$item['quantity'];if($variantId>0){$update=$conn->prepare('UPDATE product_variants SET stock_quantity=stock_quantity+? WHERE id=?');$update->bind_param('ii',$quantity,$variantId);$update->execute();$update->close();sync_product_stock_from_variants($conn,$productId);$update2=$conn->prepare('UPDATE products SET sales_count=GREATEST(0,sales_count-?) WHERE id=?');$update2->bind_param('ii',$quantity,$productId);$update2->execute();$update2->close();}else{$update=$conn->prepare('UPDATE products SET stock_quantity=stock_quantity+?,sales_count=GREATEST(0,sales_count-?) WHERE id=?');$update->bind_param('iii',$quantity,$quantity,$productId);$update->execute();$update->close();}}$itemsStmt->close();$updateOrder=$conn->prepare("UPDATE orders SET status='canceled',payment_status=IF(payment_status='paid',payment_status,'failed') WHERE id=? AND user_id=?");$updateOrder->bind_param('ii',$order_id,$user_id);$updateOrder->execute();$updateOrder->close();log_order_status($conn,$order_id,'canceled','Khách hàng tự hủy đơn',order_history_customer_actor($_SESSION['fullname']??''));$logMessage='Khách hàng đã hủy đơn hàng '.$order_id;$logStmt=$conn->prepare('INSERT INTO purchase_logs (order_id,log_message,created_at) VALUES (?,?,NOW())');$logStmt->bind_param('is',$order_id,$logMessage);$logStmt->execute();$logStmt->close();$_SESSION['msg']=['type'=>'success','text'=>'Đã hủy đơn hàng thành công!'];}else{$_SESSION['msg']=['type'=>'error','text'=>'Không thể hủy đơn hàng này!'];}$check->close();header('Location: '.$base_url.'don-hang');exit();}
require_once 'header.php';$msg_type='';$msg_text='';if(isset($_SESSION['msg'])){$msg_type=$_SESSION['msg']['type'];$msg_text=$_SESSION['msg']['text'];unset($_SESSION['msg']);}
$page=max(1,(int)($_GET['page']??1));$limit=6;$countStmt=$conn->prepare('SELECT COUNT(*) total FROM orders WHERE user_id=?');$countStmt->bind_param('i',$user_id);$countStmt->execute();$total_rows=(int)$countStmt->get_result()->fetch_assoc()['total'];$countStmt->close();$total_pages=max(1,(int)ceil($total_rows/$limit));$page=min($page,$total_pages);$offset=($page-1)*$limit;$stmt=$conn->prepare("SELECT * FROM orders WHERE user_id=? ORDER BY id DESC LIMIT $limit OFFSET $offset");$stmt->bind_param('i',$user_id);$stmt->execute();$result=$stmt->get_result();$summaryStmt=$conn->prepare("SELECT COUNT(*) total,COALESCE(SUM(CASE WHEN payment_status='paid' THEN total_money ELSE 0 END),0) spent,SUM(status='pending') pending,SUM(status='processing') processing FROM orders WHERE user_id=?");$summaryStmt->bind_param('i',$user_id);$summaryStmt->execute();$summary=$summaryStmt->get_result()->fetch_assoc();$summaryStmt->close();
?>
<style>
