rk);font-size:18px}.payment-pill{padding:5px 8px;border-radius:8px;background:#f7f3ee;color:#84654f;font-size:12px}.payment-pill.paid{background:#edf6f0;color:#55755e}.timeline{margin:13px 0;display:grid;grid-template-columns:repeat(3,1fr);position:relative}.timeline:before{content:'';position:absolute;left:9%;right:9%;top:12px;height:2px;background:var(--line)}.timeline-step{position:relative;z-index:1;text-align:center;color:#9a918b;font-size:11px}.timeline-step i{width:25px;height:25px;border-radius:50%;background:#fff;border:2px solid var(--line);display:flex;align-items:center;justify-content:center;margin:0 auto 4px}.timeline-step.active{color:var(--primary-dark)}.timeline-step.active i{background:var(--primary);border-color:var(--primary);color:#fff}.order-actions{display:flex;justify-content:flex-end;gap:6px;align-items:center}.order-actions form{margin:0}.btn-view,.btn-pay,.btn-cancel{height:34px;padding:0 10px;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;gap:6px;font-weight:bold;font-size:13px}.btn-view{border:1px solid var(--line);background:#fff;color:var(--primary-dark)}.btn-pay{border:0;background:var(--primary);color:#fff}.btn-cancel{border:0;background:#b45c57;color:#fff;cursor:pointer}.empty-orders{padding:55px;text-align:center;border:1px solid var(--line);border-radius:12px}.empty-orders i{font-size:37px;color:#c5aa91}.empty-orders h3{margin:10px 0;color:var(--primary-dark)}.modal-box{display:none;position:fixed;inset:0;z-index:1600;padding:14px;background:rgba(67,54,45,.42);align-items:center;justify-content:center}.modal-box.show{display:flex}.modal-content{width:min(760px,100%);max-height:92vh;border-radius:12px;background:#fff;overflow:auto}.modal-header,.modal-footer{padding:13px 15px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.modal-footer{border-bottom:0;border-top:1px solid var(--line);justify-content:flex-end}.modal-body{padding:15px}.delivery-box{padding:10px;border:1px solid var(--line);border-radius:9px;background:#fbfaf8;display:grid;gap:6px}.items-container{margin-top:10px;display:grid;gap:7px}.item-card{padding:8px;border:1px solid var(--line);border-radius:9px;display:grid;grid-template-columns:60px 1fr auto;gap:8px;align-items:center}.item-card-img{width:60px;height:52px;object-fit:contain;background:#fbfaf8}.modal-total{margin-top:10px;padding-top:10px;border-top:1px solid var(--line);display:flex;justify-content:space-between}.modal-total strong{color:var(--primary-dark)}@media(max-width:760px){.summary-grid{grid-template-columns:repeat(2,1fr)}.order-card{grid-template-columns:1fr}.order-card-head{border-right:0;border-bottom:1px solid var(--line);flex-direction:row;align-items:center}.order-money{align-items:flex-start;flex-direction:column}.order-actions{justify-content:flex-start;flex-wrap:wrap}}.history-timeline{margin-top:14px;padding-top:12px;border-top:1px solid var(--line)}.coupon-tag{display:block;margin-top:4px;color:#16a34a;font-size:12px;font-weight:bold}.history-timeline h4{margin-bottom:8px;color:var(--primary-dark);font-size:14px}.history-item{position:relative;padding:0 0 14px 20px;border-left:2px solid var(--line)}.history-item:last-child{border-color:transparent;padding-bottom:0}.history-item:before{content:'';position:absolute;left:-6px;top:2px;width:10px;height:10px;border-radius:50%;background:var(--primary)}.history-item .h-status{font-weight:bold;color:var(--primary-dark);font-size:13px}.history-item .h-note{color:var(--muted);font-size:12px;margin-top:2px}.history-item .h-meta{color:#b3a89c;font-size:11px;margin-top:2px}
