<div class="container orders-page"><div class="breadcrumb"><a href="<?php echo $base_url; ?>"><i class="fas fa-home"></i> Trang chủ</a><i class="fas fa-chevron-right"></i><span>Đơn hàng</span></div><section class="orders-head"><div><h1>Đơn hàng của tôi</h1><p>Theo dõi thanh toán và tiến độ xử lý từng đơn trên cùng một màn hình.</p></div><i class="fas fa-boxes-stacked"></i></section><section class="summary-grid"><div class="summary-card"><i class="fas fa-receipt"></i><div><span>Tổng đơn hàng</span><strong><?php echo number_format((int)$summary['total']); ?></strong></div></div><div class="summary-card"><i class="fas fa-clock"></i><div><span>Chờ xử lý</span><strong><?php echo number_format((int)$summary['pending']); ?></strong></div></div><div class="summary-card"><i class="fas fa-truck-fast"></i><div><span>Đang giao</span><strong><?php echo number_format((int)$summary['processing']); ?></strong></div></div><div class="summary-card"><i class="fas fa-credit-card"></i><div><span>Đã thanh toán</span><strong><?php echo number_format((float)$summary['spent'],0,',','.'); ?> đ</strong></div></div></section><?php if($result->num_rows>0):?><section class="orders-grid"><?php while($row=$result->fetch_assoc()):$labels=['pending'=>'Chờ xử lý','processing'=>'Đang giao','completed'=>'Hoàn thành','canceled'=>'Đã hủy'];$payMethods=['cod'=>'COD','vnpay'=>'VNPay'];$payStatuses=['unpaid'=>'Chưa thanh toán','pending'=>'Chờ thanh toán','paid'=>'Đã thanh toán','failed'=>'Chưa thành công'];?><article class="order-card"><div class="order-card-head"><div class="order-code"><strong>Đơn hàng <?php echo $row['id']; ?></strong><span><i class="far fa-clock"></i> <?php echo date('H:i d/m/Y',strtotime($row['created_at'])); ?></span></div><span class="status-badge status-<?php echo htmlspecialchars($row['status']); ?>"><?php echo $labels[$row['status']]??$row['status']; ?></span></div><div class="order-main"><div class="order-money"><div><span>Tổng thanh toán</span><strong><?php echo number_format($row['total_money'],0,',','.'); ?> đ</strong><?php if(!empty($row['coupon_code'])&&(float)$row['discount_amount']>0):?><small class="coupon-tag"><i class="fas fa-tag"></i> <?php echo htmlspecialchars($row['coupon_code']); ?> (-<?php echo number_format($row['discount_amount'],0,',','.'); ?> đ)</small><?php endif;?></div><div class="payment-pill <?php echo $row['payment_status']==='paid'?'paid':''; ?>"><?php echo htmlspecialchars(($payMethods[$row['payment_method']]??$row['payment_method']).' · '.($payStatuses[$row['payment_status']]??$row['payment_status'])); ?></div></div><div class="timeline"><div class="timeline-step <?php echo in_array($row['status'],['pending','processing','completed'],true)?'active':''; ?>"><i class="fas fa-box"></i><span>Tiếp nhận</span></div><div class="timeline-step <?php echo in_array($row['status'],['processing','completed'],true)?'active':''; ?>"><i class="fas fa-truck"></i><span>Đang giao</span></div><div class="timeline-step <?php echo $row['status']==='completed'?'active':''; ?>"><i class="fas fa-circle-check"></i><span>Hoàn thành</span></div></div><div class="order-actions"><button class="btn-view" type="button" onclick="viewOrder(<?php echo $row['id']; ?>)"><i class="fas fa-eye"></i> Chi tiết</button><?php if($row['payment_method']==='vnpay'&&$row['payment_status']!=='paid'&&$row['status']==='pending'):?><a class="btn-pay" href="<?php echo $base_url; ?>payment.php?order_id=<?php echo $row['id']; ?>"><i class="fas fa-credit-card"></i> Thanh toán</a><?php endif;?><?php if($row['status']==='pending'&&$row['payment_status']!=='paid'):?><form method="POST" onsubmit="return confirmCancel(event,this)"><?php echo csrf_field(); ?><input type="hidden" name="action" value="cancel_order"><input type="hidden" name="order_id" value="<?php echo $row['id']; ?>"><button class="btn-cancel" type="submit"><i class="fas fa-xmark"></i> Hủy đơn</button></form><?php endif;?></div></div></article><?php endwhile;?></section><?php if($total_pages>1):?><nav class="pagination"><?php for($i=1;$i<=$total_pages;$i++):?><a class="page-link <?php echo $page===$i?'active':''; ?>" href="?page=<?php echo $i; ?>"><?php echo $i; ?></a><?php endfor;?></nav><?php endif;?><?php else:?><div class="empty-orders"><i class="fas fa-box-open"></i><h3>Chưa có đơn hàng nào</h3><p>Bạn chưa thực hiện giao dịch nào trên hệ thống.</p><a href="<?php echo $base_url; ?>san-pham">Xem sản phẩm</a></div><?php endif;?></div><div class="modal-box js-view-modal"><div class="modal-content"><div class="modal-header"><h3 class="modal-title">Chi tiết đơn hàng <span id="v_order_id"></span></h3><i class="fas fa-xmark close-modal" onclick="closeModal('js-view-modal')"></i></div><div class="modal-body"><div class="delivery-box"><div><i class="fas fa-user"></i> <span id="v_fullname"></span></div><div><i class="fas fa-phone"></i> <span id="v_phone"></span></div><div><i class="fas fa-location-dot"></i> <span id="v_address"></span></div></div><div class="items-container" id="v_items_container"></div><div class="history-timeline" id="v_history"></div><div class="modal-total" id="v_discount_row" style="display:none;"><span>Giảm giá</span><strong id="v_discount" style="color:#16a34a"></strong></div><div class="modal-total"><span>Tổng thanh toán</span><strong id="v_total"></strong></div></div><div class="modal-footer"><button type="button" onclick="closeModal('js-view-modal')">Đóng</button></div></div></div><script>const orderMediaBase=<?php echo json_encode($base_url.'uploads/',JSON_UNESCAPED_SLASHES); ?>;function resolveOrderMedia(value){value=String(value||'').trim();if(!value)return'https://placehold.co/100x100?text=No+Img';if(/^https?:\/\//i.test(value))return value;value=value.replace(/\\/g,'/').replace(/^(?:\.\.\/|\.\/)+/,'').replace(/^\/+/, '').replace(/^uploads\//i,'');return orderMediaBase+value.split('/').filter(Boolean).map(encodeURIComponent).join('/')}function formatMoney(amount){return new Intl.NumberFormat('vi-VN').format(amount)+' đ'}function openModal(className){document.querySelector('.'+className).classList.add('show')}function closeModal(className){document.querySelector('.'+className).classList.remove('show')}function confirmCancel(event,form){event.preventDefault();Swal.fire({title:'Hủy đơn hàng?',text:'Bạn có chắc chắn muốn hủy đơn hàng này không?',icon:'warning',showCancelButton:true,confirmButtonColor:'#b65757',cancelButtonColor:'#667681',confirmButtonText:'Đồng ý hủy',cancelButtonText:'Không'}).then(function(result){if(result.isConfirmed)form.submit()});return false}async function viewOrder(id){Swal.fire({title:'Đang tải...',allowOutsideClick:false,didOpen:function(){Swal.showLoading()}});try{const res=await fetch('?ajax_action=get_details&id='+id);const data=await res.json();Swal.close();if(data.status!=='success')throw new Error('Không thể tải chi tiết đơn hàng');const o=data.order;document.getElementById('v_order_id').textContent=o.id;document.getElementById('v_fullname').textContent=o.fullname;document.getElementById('v_phone').textContent=o.phone;document.getElementById('v_address').textContent=o.shipping_address;document.getElementById('v_total').textContent=formatMoney(o.total_money);const discountRow=document.getElementById('v_discount_row');if(o.discount_amount&&parseFloat(o.discount_amount)>0){discountRow.style.display='';document.getElementById('v_discount').textContent='-'+formatMoney(o.discount_amount)+(o.coupon_code?' ('+o.coupon_code+')':'')}else{discountRow.style.display='none'}const container=document.getElementById('v_items_container');container.innerHTML='';data.items.forEach(function(item){const img=item.image_url||resolveOrderMedia(item.image);const card=document.createElement('div');card.className='item-card';card.innerHTML='<img src="'+img+'" class="item-card-img" alt=""><div><div class="item-card-name"></div><div class="item-card-meta"></div></div><div class="item-card-total"></div>';card.querySelector('.item-card-name').textContent=item.name+(item.variant_name?' ('+item.variant_name+')':'');card.querySelector('.item-card-meta').textContent=formatMoney(item.price)+' × '+item.quantity;card.querySelector('.item-card-total').textContent=formatMoney(item.price*item.quantity);container.appendChild(card)});const histBox=document.getElementById('v_history');const statusLabels={pending:'Chờ xác nhận',processing:'Đang xử lý',completed:'Hoàn thành',canceled:'Đã hủy'};histBox.innerHTML='<h4>Lịch sử đơn hàng</h4>'+(data.history||[]).map(function(h){const label=statusLabels[h.status]||h.status;const time=h.created_at?new Date(h.created_at.replace(' ','T')).toLocaleString('vi-VN'):'';return '<div class="history-item"><div class="h-status">'+label+'</div>'+(h.note?'<div class="h-note">'+h.note+'</div>':'')+'<div class="h-meta">'+(h.changed_by||'')+' · '+time+'</div></div>'}).join('');openModal('js-view-modal')}catch(error){Swal.close();Swal.fire('Lỗi!',error.message||'Mất kết nối máy chủ','error')}}<?php if($msg_type!==''): ?>document.addEventListener('DOMContentLoaded',function(){Swal.fire({icon:<?php echo json_encode($msg_type); ?>,title:<?php echo json_encode($msg_type==='success'?'Thành công':'Lỗi',JSON_UNESCAPED_UNICODE); ?>,text:<?php echo json_encode($msg_text,JSON_UNESCAPED_UNICODE); ?>,confirmButtonColor:'#27699a',timer:2500})});<?php endif; ?></script><?php $stmt->close(); require_once 'footer.php'; ?>
